"""Neon Air Hockey preview, privacy and support — maintained publishing source."""
from pathlib import Path
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[1]
def build(page):
 base='/assets/apps/neon-air-hockey/'
 body=f'''<style>.hockey-hero{{display:grid;grid-template-columns:1.2fr 1fr;align-items:center;gap:2rem}}.hockey-art{{width:100%;height:auto;aspect-ratio:1;object-fit:contain;border-radius:28px}}.hockey-features{{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}}.hockey-features article{{padding:1.3rem;border:1px solid #3d526d;border-radius:18px;background:#101a2c}}@media(max-width:650px){{.hockey-hero,.hockey-features{{grid-template-columns:1fr}}.hockey-art{{max-width:340px;margin:auto}}}}</style>
 <section class="catalog-hero hockey-hero"><div><p class="eyebrow">Android arcade game · In development</p><h1>Neon Air Hockey</h1><p class="lead">One rink. Two rivals.</p><p>Turn your phone or tablet into a neon air-hockey table. Take on the computer or put a friend at the other end of the screen. Slide, strike and race to seven.</p><p><a class="button" href="#screenshots">See the game</a> · <a href="/neon-air-hockey/support/">How to play</a></p><p>Coming soon. Not yet available on Google Play.</p></div><img class="hockey-art" src="{base}icon.webp" width="768" height="768" alt="Neon cyan and coral hockey mallets beside a glowing puck"></section>
 <section><h2>Your next face-off</h2><div class="hockey-features"><article><h3>Challenge the computer</h3><p>Choose Relaxed, Balanced or Fast. Practice your aim, defend your goal and find an opening.</p></article><article><h3>Two players. One screen.</h3><p>Set a phone or tablet between you. Each player controls a mallet on their half, with both fingers moving at once.</p></article><article><h3>Keep the action moving</h3><p>Pause with one tap. Reset a stuck puck without losing the score. Resume your saved local match when you return.</p></article></div></section>
 <section id="screenshots"><h2>See it on the rink</h2><p>Actual Android development-build screenshots. Features and appearance may change before release.</p><div class="screenshots"><figure><img src="{base}home.webp" width="1080" height="2376" loading="lazy" alt="Neon Air Hockey menu with computer, two-player and Bluetooth modes"><figcaption>Choose a mode and jump in.</figcaption></figure><figure><img src="{base}game.webp" width="1080" height="2376" loading="lazy" alt="Full-screen neon rink with matching reset and pause icon buttons"><figcaption>A full-screen rink with compact controls.</figcaption></figure></div></section>
 <section><h2>Bluetooth play is in testing</h2><p>The development build includes <strong>Host a game</strong> and <strong>Join a game</strong> for paired phones. One phone runs the match while the other sends its mallet movements. Two-phone gameplay and connection quality are still being verified, so Bluetooth is not yet a verified release feature.</p><h2>Simple play, clear limits</h2><p>Local gameplay works offline, with optional puck sounds and no account. Full-screen test ads appear only between completed matches, when you choose a rematch or return Home. Close the ad to continue; if none is available, play continues. Ads require internet. Launch pricing has not been announced.</p><p>Optional Android screen pinning can reduce accidental exits during same-screen play. System gestures and pinning vary by device; the game cannot guarantee that every phone blocks its menus.</p></section><p><a href="/neon-air-hockey/privacy/">Privacy policy</a> · <a href="/neon-air-hockey/support/">Support</a></p>'''
 page('/neon-air-hockey/','Neon Air Hockey — Android Air Hockey Game','Challenge the computer or a friend on the same screen in Neon Air Hockey for Android. Full-screen neon rink, local saves and puck reset. Coming soon.',body,'https://tripperdeelabs.com'+base+'icon.webp')
 page('/neon-air-hockey/privacy/','Neon Air Hockey privacy policy','How Neon Air Hockey handles local saves, optional Bluetooth, test ads and support.', '''<section><h1>Neon Air Hockey privacy policy</h1><p>Updated November 6, 2026. This policy describes the current Android development build, package com.tripperdeelabs.neonairhockey, provided by TripperDeeLabs.</p><h2>Local game data</h2><p>Scores, your saved local match, difficulty and sound preferences are stored in the app on your device. There is no TripperDeeLabs account or cloud-save service. Uninstalling or clearing app storage removes this data. The app disables Android backup through its manifest; device transfer behavior may vary by Android version and manufacturer.</p><h2>Optional Bluetooth</h2><p>Bluetooth play uses Android’s paired devices and Nearby devices permission on supported Android versions. It sends live match state and mallet movements directly to your opponent. The app does not upload those match messages to a TripperDeeLabs server. Leaving the app ends the connection. Local games do not need Bluetooth permission.</p><h2>Advertising</h2><p>The development build uses Google Mobile Ads SDK and Google test interstitials between completed matches. Production ads are disabled. The SDK communicates with Google and may process IP addresses, device information, diagnostics and ad interactions for ad delivery, security and measurement. Current requests use G-rated, child-directed and under-age-of-consent treatment flags. These settings are not a claim that a production Families release has been approved. No developer-operated analytics SDK is included.</p><p>See <a href="https://policies.google.com/privacy">Google’s privacy policy</a>. Production advertising, audience and consent configuration must be completed before release, and this policy will be updated if practices change.</p><h2>Permissions and choices</h2><p>Internet and network-state access support ads. The app does not request location, camera, microphone or contacts access. You can decline Nearby devices permission and continue local play. There are no purchases in the current build.</p><h2>Support</h2><p>If you email <a href="mailto:tripperdeelabs@gmail.com">tripperdeelabs@gmail.com</a>, we receive the information you send and use it to respond. Avoid sending passwords or payment details. Contact that address with privacy questions or requests concerning support correspondence.</p><p>Website analytics are separate from the Android game and covered by the <a href="/privacy/">website privacy policy</a>.</p><p><a href="/neon-air-hockey/">Game overview</a> · <a href="/neon-air-hockey/support/">Support</a></p></section>''')
 page('/neon-air-hockey/support/','Neon Air Hockey support','Controls, puck reset, Bluetooth pairing, ads and troubleshooting for Neon Air Hockey.', '''<section><h1>Neon Air Hockey support</h1><h2>Play a match</h2><p>Drag on your half of the rink to move your mallet. Cyan plays at the bottom, coral at the top. Score through the opening at the other end. First to seven wins. Choose Play computer for a solo game, or Two players to share one screen.</p><h2>Pause, reset and save</h2><p>The two-bar icon pauses play. The circular-arrow icon resets the puck and mallets for a new face-off without changing the score. Home keeps your local match; Resume match brings it back. Starting another local match asks before replacing it. Open the gear for sound, difficulty and optional Android screen pinning.</p><h2>Bluetooth: Host or Join</h2><p>This feature is still undergoing two-phone validation. Install the same app version on both phones, enable Bluetooth, and pair them in Android Bluetooth settings. Open Bluetooth play and grant Nearby devices permission. Choose Host a game on one phone, then Join a game on the other and select the host. Each player sees their own mallet at the bottom. Leaving the foreground or losing the connection ends the session; reconnect to start again. Your saved local match is kept separately.</p><h2>Between-match ads</h2><p>Current builds use Google test ads. A full-screen ad may appear after a completed match when you choose Rematch or Home. Use the ad’s Close button when it becomes available. The next local match starts after dismissal. If an ad is unavailable, continue immediately. Bluetooth sessions close before an ad; host and join again for another match.</p><h2>Troubleshooting</h2><p>Use Reset if the puck gets trapped. Keep fingers inside the rails to reduce Android edge gestures. Screen pinning is optional and device-dependent; follow Android’s unpin instructions or use Unpin game in Settings. Do not uninstall or clear storage if you want to keep your saved match.</p><p>Email <a href="mailto:tripperdeelabs@gmail.com?subject=Neon%20Air%20Hockey%20support">tripperdeelabs@gmail.com</a> with your app version, device model and what happened.</p><p><a href="/neon-air-hockey/">Game overview</a> · <a href="/neon-air-hockey/privacy/">Privacy policy</a></p></section>''')
 home=ROOT/'index.html';soup=BeautifulSoup(home.read_text(),'html.parser');listing=soup.select_one('#in-development .app-directory');assert listing is not None
 listing.insert(0,BeautifulSoup(f'<li><a class="directory-preview" href="/neon-air-hockey/"><img src="{base}game.webp" width="1080" height="2376" loading="lazy" alt="Neon Air Hockey rink"></a><div class="directory-copy"><h3><a href="/neon-air-hockey/">Neon Air Hockey</a></h3><p class="availability">Coming soon</p><p>Challenge the computer or a friend on one screen. A neon rink, first-to-seven matches and simple touch controls.</p><p><a href="/neon-air-hockey/">Explore the game</a> · <a href="/neon-air-hockey/privacy/">Privacy</a></p></div></li>','html.parser').li);home.write_text(str(soup))
